        .duration_since(std::time::UNIX_EPOCH)
        .unwrap_or_default()
        .as_secs() as i64;
    let start = (now + 86400).to_string();
    let end = (now + 90000).to_string();

    // S7-1: event_create returns a new event with id and version=1.
    match mcp_call_tool(
        ctx,
        &access,
